import spidev
import time
import signal
import sys

class LoadCellReader:
    def __init__(self, bus=0, device=0):
        self.spi = spidev.SpiDev()
        self.spi.open(bus, device)
        self.spi.max_speed_hz = 50000
        self.spi.mode = 0b00
        self.spi.bits_per_word = 8

    def send_spi_command(self, spi, data):
        try:
            response = spi.xfer2(data)
            return response
        except (OSError, IOError) as e:
            print(f"SPI transfer error: {e}")
            return None

    def extract_10bit(self, response):
        if response is None or len(response) < 3:
            return None
        return ((response[1] & 0x03) << 8) | response[2]

    def read_raw_data(self):
        command = [0x01, 0x80, 0x00]
        response = self.send_spi_command(self.spi, command)
        raw_data = self.extract_10bit(response)
        return raw_data

    def convert_to_weight(self, raw_data):
        if raw_data is None:
            return None
        weight = float(raw_data) * (5.0 / 1023.0)
        return weight

    def close(self):
        self.spi.close()
        print("SPI device closed.")

def signal_handler(sig, frame):
    print("Received signal to terminate.")
    sys.exit(0)

def main():
    signal.signal(signal.SIGTERM, signal_handler)
    reader = LoadCellReader()
    try:
        while True:
            raw_data = reader.read_raw_data()
            weight = reader.convert_to_weight(raw_data)
            if weight is not None:
                print(f"Weight: {weight:.2f} kg")
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("KeyboardInterrupt received.")
    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        reader.close()
        print("Program shutting down.")

if __name__ == "__main__":
    main()

