import smbus2
import signal
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ADS1015:
    def __init__(self, address=0x48, busnum=1, debug=False):
        self.address = address
        self.busnum = busnum
        self.debug = debug
        self.bus = smbus2.SMBus(busnum)
        self._verify_device()

    def _verify_device(self):
        try:
            config = self.bus.read_i2c_block_data(self.address, 0x01, 2)
            if self.debug:
                logging.info(f"Device config register: {config}")
        except (smbus2.SMBusError, OSError) as e:
            logging.error(f"Failed to read config register: {e}")
            raise

    def read_adc_single_ended(self, channel=0, pga=6144, sps=250):
        if not 0 <= channel <= 3:
            raise ValueError("Channel must be between 0 and 3")
        config = self._build_config(channel, pga, sps, single_shot=True)
        self._write_config(config)
        return self._read_conversion()

    def start_continuous_conversion(self, channel=0, pga=6144, sps=250):
        if not 0 <= channel <= 3:
            raise ValueError("Channel must be between 0 and 3")
        config = self._build_config(channel, pga, sps, single_shot=False)
        self._write_config(config)

    def get_last_conversion_results(self):
        return self._read_conversion()

    def start_single_ended_comparator(self, channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        if not 0 <= channel <= 3:
            raise ValueError("Channel must be between 0 and 3")
        config = self._build_config(channel, pga, sps, comparator=True, threshold_high=threshold_high, threshold_low=threshold_low, active_low=active_low, traditional_mode=traditional_mode, latching=latching, num_readings=num_readings)
        self._write_config(config)

    def _build_config(self, channel, pga, sps, single_shot=True, comparator=False, threshold_high=None, threshold_low=None, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        config = 0x8000  # Start bit
        if single_shot:
            config |= 0x0100
        if comparator:
            config |= 0x0080
            config |= (threshold_high & 0xFFF) << 4
            config |= (threshold_low & 0xFFF) << 12
            config |= (0x01 if active_low else 0x00) << 11
            config |= (0x01 if traditional_mode else 0x00) << 10
            config |= (0x01 if latching else 0x00) << 8
            config |= (num_readings & 0x07) << 5
        else:
            config |= (0x00 if single_shot else 0x01) << 8
        config |= (channel & 0x03) << 12
        config |= (pga & 0x07) << 9
        config |= (sps & 0x07) << 5
        return config

    def _write_config(self, config):
        try:
            self.bus.write_i2c_block_data(self.address, 0x01, [(config >> 8) & 0xFF, config & 0xFF])
        except (smbus2.SMBusError, OSError) as e:
            logging.error(f"Failed to write config: {e}")

    def _read_conversion(self):
        try:
            data = self.bus.read_i2c_block_data(self.address, 0x00, 2)
            value = (data[0] << 8) | data[1]
            if value & 0x8000:
                value -= 1 << 12
            return value
        except (smbus2.SMBusError, OSError) as e:
            logging.error(f"Failed to read conversion: {e}")
            return None

    def __del__(self):
        self._close_bus()

    def _close_bus(self):
        try:
            self.bus.close()
        except (smbus2.SMBusError, OSError) as e:
            logging.error(f"Failed to close I2C bus: {e}")

def signal_handler(sig, frame):
    logging.info("Received signal to exit")
    ads1015._close_bus()
    exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ads1015 = ADS1015(debug=True)
    try:
        value = ads1015.read_adc_single_ended(channel=0)
        logging.info(f"ADC value: {value}")
    finally:
        ads1015._close_bus()

