import spidev
import time
import sys

def read_mcp3008(channel, spi):
    if channel < 0 or channel > 7:
        raise ValueError("Channel must be between 0 and 7")

    adc = spi.xfer2([0x01, (0x08 | channel) << 4, 0x00])
    data = ((adc[1] & 0x03) << 8) | adc[2]
    return data

def main():
    spi = None
    try:
        spi = spidev.SpiDev()
        spi.open(0, 0)
        spi.max_speed_hz = 1350000

        for _ in range(5):
            try:
                raw_value = read_mcp3008(0, spi)
                moisture_percentage = round((raw_value / 1023.0) * 100, 2)
                print(f"Soil moisture level: {moisture_percentage}%")
                time.sleep(2)
            except Exception as e:
                print(f"Error reading from MCP3008: {e}")
                sys.exit(1)

        print("Soil moisture reading sequence completed.")

    except KeyboardInterrupt:
        print("Script interrupted by user.")

    finally:
        if spi:
            spi.close()
            print("SPI connection closed.")

if __name__ == "__main__":
    main()

import spidev
import RPi.GPIO as GPIO
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SmartGardenController:
    def __init__(self, spi_bus=0, spi_device=0, spi_speed=1350000, pump_pin=18):
        self.spi = spidev.SpiDev()
        try:
            self.spi.open(spi_bus, spi_device)
            self.spi.max_speed_hz = spi_speed
        except Exception as e:
            logging.error(f"Failed to open SPI bus: {e}")
            raise

        self.pump_pin = pump_pin
        GPIO.setmode(GPIO.BCM)
        try:
            GPIO.setup(self.pump_pin, GPIO.OUT)
        except Exception as e:
            logging.error(f"Failed to set up GPIO pin {self.pump_pin}: {e}")
            self.spi.close()
            raise

    def read_moisture(self):
        try:
            # MCP3008 command format: start bit (1), single-ended mode (1), channel select (3 bits)
            command = [0b11 << 6, 0b10 << 4, 0b000 << 1]
            response = self.spi.xfer2(command)
            # Combine the two bytes to get the 10-bit result
            adc_value = ((response[1] & 0x03) << 8) | response[2]
            return adc_value
        except Exception as e:
            logging.error(f"SPI transaction failed: {e}")
            return None

    def run_pump(self, seconds):
        try:
            GPIO.output(self.pump_pin, GPIO.HIGH)
            time.sleep(seconds)
            GPIO.output(self.pump_pin, GPIO.LOW)
        except Exception as e:
            logging.error(f"Failed to control pump: {e}")

    def irrigation_cycle(self):
        moisture_value = self.read_moisture()
        if moisture_value is not None:
            logging.info(f"Moisture value: {moisture_value}")
            if moisture_value > 450:
                self.run_pump(2)
                return True
        return False

    def close(self):
        GPIO.cleanup(self.pump_pin)
        self.spi.close()

def schedule_cycles(controller, cycle_count, interval_seconds):
    for i in range(cycle_count):
        watered = controller.irrigation_cycle()
        logging.info(f"Cycle {i+1}: {'Watered' if watered else 'Not watered'}")
        time.sleep(interval_seconds)

if __name__ == "__main__":
    controller = None
    try:
        controller = SmartGardenController()
        schedule_cycles(controller, 10, 3)
    except KeyboardInterrupt:
        logging.info("Interrupted by user")
    finally:
        if controller:
            controller.close()
            logging.info("Controller resources released")

