import RPi.GPIO as GPIO
import spidev
import time
import logging
import queue
import threading
import argparse

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.running = False
        self.spi = None
        self.last_event_time = 0

        if self.sensor_type == 'digital':
            GPIO.setmode(GPIO.BCM)
            for pin in self.gpio_pins:
                GPIO.setup(pin, GPIO.IN)
        elif self.sensor_type == 'analog':
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = self.spi_speed
        else:
            raise ValueError("Invalid sensor type. Use 'digital' or 'analog'.")

    def read_digital(self):
        for pin in self.gpio_pins:
            if GPIO.input(pin) == 1:
                return True
        return False

    def read_analog(self, channel):
        if not (0 <= channel < 8):
            logging.error(f"Invalid channel {channel} for MCP3008.")
            return None
        adc = self.spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data

    def detect_event(self):
        if self.sensor_type == 'digital':
            return self.read_digital()
        elif self.sensor_type == 'analog':
            for channel in self.channels:
                value = self.read_analog(channel)
                if value is not None and value >= self.threshold:
                    return True
        return False

    def run(self):
        self.running = True
        while self.running:
            if self.detect_event():
                current_time = time.time()
                if current_time - self.last_event_time > 0.1:
                    self.last_event_time = current_time
                    if self.log_queue:
                        self.log_queue.put(f"Sensor {self.sensor_id} detected sound at {time.strftime('%Y-%m-%d %H:%M:%S')}")
            time.sleep(1 / self.sample_rate)

    def stop(self):
        self.running = False
        if self.sensor_type == 'digital':
            GPIO.cleanup(self.gpio_pins)
        if self.spi:
            self.spi.close()

def worker(sensor):
    try:
        sensor.run()
    except Exception as e:
        logging.error(f"Error in sensor {sensor.sensor_id}: {e}")
    finally:
        sensor.stop()

def main():
    parser = argparse.ArgumentParser(description="Sound Sensor Monitoring")
    parser.add_argument('--sensor_type', required=True, choices=['digital', 'analog'])
    parser.add_argument('--threshold', type=int, required=True)
    parser.add_argument('--sample_rate', type=float, required=True)
    parser.add_argument('--log_file', required=True)
    parser.add_argument('--gpio_pins', nargs='+', type=int, default=[])
    parser.add_argument('--channels', nargs='+', type=int, default=[])
    parser.add_argument('--spi_speed', type=int, default=1000000)
    parser.add_argument('--sensor_ids', nargs='+', required=True)

    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
    log_queue = queue.Queue()

    sensors = []
    for sensor_id in args.sensor_ids:
        sensor = SoundSensor(
            sensor_id=sensor_id,
            sensor_type=args.sensor_type,
            threshold=args.threshold,
            sample_rate=args.sample_rate,
            gpio_pins=args.gpio_pins,
            channels=args.channels,
            spi_speed=args.spi_speed,
            log_queue=log_queue
        )
        sensors.append(sensor)

    threads = []
    for sensor in sensors:
        thread = threading.Thread(target=worker, args=(sensor,))
        threads.append(thread)
        thread.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Shutting down gracefully...")
    finally:
        for sensor in sensors:
            sensor.stop()
        for thread in threads:
            thread.join()

if __name__ == "__main__":
    main()

