import json
import queue
import threading
import time
import signal
import sys
import RPi.GPIO as GPIO
from gpiozero import LED
from picamera2 import Picamera2
from paho.mqtt import client as mqtt

# Global variables
config = {}
camera = None
led = None
capture_queue = None
mqtt_client = None

def load_config(config_file):
    global config
    try:
        with open(config_file, 'r') as file:
            config = json.load(file)
    except FileNotFoundError:
        print("Config file not found.")
        sys.exit(1)
    except json.JSONDecodeError:
        print("Error decoding JSON from config file.")
        sys.exit(1)

def initialize_camera():
    global camera
    try:
        camera = Picamera2()
        camera_config = camera.create_still_configuration(main={"size": (config['resolution']['width'], config['resolution']['height'])})
        camera.configure(camera_config)
        camera.start()
        time.sleep(2)  # Camera warm-up time
    except Exception as e:
        print(f"Error initializing camera: {e}")
        sys.exit(1)

def initialize_led():
    global led
    if 'gpio_pin' in config:
        try:
            led = LED(config['gpio_pin'])
        except Exception as e:
            print(f"Error initializing LED: {e}")
            sys.exit(1)

def initialize_mqtt():
    global mqtt_client
    if 'mqtt_broker' in config:
        try:
            mqtt_client = mqtt.Client()
            mqtt_client.on_connect = on_connect
            mqtt_client.on_message = on_message
            mqtt_client.connect(config['mqtt_broker'], config.get('mqtt_port', 1883), 60)
            mqtt_client.loop_start()
        except Exception as e:
            print(f"Error initializing MQTT: {e}")
            sys.exit(1)

def on_connect(client, userdata, flags, rc):
    print(f"Connected with result code {rc}")
    if 'mqtt_topic' in config:
        client.subscribe(config['mqtt_topic'])

def on_message(client, userdata, msg):
    print(f"Message received: {msg.topic} {msg.payload}")

def capture_frames():
    global capture_queue
    try:
        capture_queue = queue.Queue(maxsize=config['queue_size'])
        while True:
            try:
                frame = camera.capture_array("main")
                capture_queue.put(frame, block=True, timeout=1)
                time.sleep(0.1)  # Sleep to avoid excessive CPU usage
            except queue.Full:
                print("Capture queue is full, dropping frame.")
            except Exception as e:
                print(f"Error capturing frame: {e}")
    except KeyboardInterrupt:
        pass

def trigger_alert():
    if led:
        try:
            led.on()
            timer = threading.Timer(config['alert_duration'], led.off)
            timer.start()
        except Exception as e:
            print(f"Error triggering alert: {e}")

def cleanup():
    global camera, led, mqtt_client
    if camera:
        camera.stop()
        camera.close()
    if led:
        led.close()
    if mqtt_client:
        mqtt_client.loop_stop()
        mqtt_client.disconnect()
    GPIO.cleanup()

def signal_handler(sig, frame):
    print("Exiting gracefully...")
    cleanup()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    load_config('config.json')
    initialize_camera()
    initialize_led()
    initialize_mqtt()
    capture_thread = threading.Thread(target=capture_frames)
    capture_thread.start()
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        pass
    cleanup()

