import serial
import picamera2
from fractions import Fraction
from typing import Tuple, Real
import os
import signal
import sys

def degrees_decimal_to_dms(degrees_decimal: float) -> Tuple[int, int, float]:
    if not isinstance(degrees_decimal, (int, float)):
        raise ValueError("Input must be a real number.")

    sign = -1 if degrees_decimal < 0 else 1
    degrees_decimal = abs(degrees_decimal)

    degrees = int(degrees_decimal)
    minutes = int((degrees_decimal - degrees) * 60)
    seconds = (degrees_decimal - degrees - minutes / 60) * 3600

    return (sign * degrees, sign * minutes, sign * seconds)

def number_to_exif_rational(number: Real) -> Tuple[int, int]:
    if not isinstance(number, (int, float)):
        raise ValueError("Input must be a real number.")

    try:
        fraction = Fraction(number).limit_denominator(1000)
    except Exception as e:
        raise ValueError("Cannot convert number to a fraction.") from e

    numerator = fraction.numerator
    denominator = fraction.denominator

    if not isinstance(numerator, int) or not isinstance(denominator, int):
        raise TypeError("Numerator and denominator must be integers.")

    return (numerator, denominator)

def capture_image_with_gps(camera: picamera2.Picamera2, gps_port: str) -> None:
    try:
        with serial.Serial(gps_port, baudrate=9600, timeout=1) as gps_serial:
            while True:
                line = gps_serial.readline().decode('utf-8').strip()
                if line.startswith('$GPGGA'):
                    parts = line.split(',')
                    if len(parts) >= 10 and parts[2] and parts[4]:
                        latitude = float(parts[2])
                        longitude = float(parts[4])
                        break

        degrees, minutes, seconds = degrees_decimal_to_dms(latitude)
        exif_latitude = (number_to_exif_rational(degrees), number_to_exif_rational(minutes), number_to_exif_rational(seconds))

        degrees, minutes, seconds = degrees_decimal_to_dms(longitude)
        exif_longitude = (number_to_exif_rational(degrees), number_to_exif_rational(minutes), number_to_exif_rational(seconds))

        exif_data = {
            'Exif.GPSInfo.GPSLatitude': exif_latitude,
            'Exif.GPSInfo.GPSLatitudeRef': 'N' if latitude >= 0 else 'S',
            'Exif.GPSInfo.GPSLongitude': exif_longitude,
            'Exif.GPSInfo.GPSLongitudeRef': 'E' if longitude >= 0 else 'W',
        }

        camera.capture_file('image_with_gps.jpg', exif_data=exif_data)
        print("Image captured with GPS data.")

    except Exception as e:
        print(f"Error: {e}")
    finally:
        camera.close()

def signal_handler(sig, frame):
    print("Exiting gracefully...")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    camera = picamera2.Picamera2()
    camera.start()

    try:
        capture_image_with_gps(camera, '/dev/serial0')
    except Exception as e:
        print(f"Error: {e}")
    finally:
        camera.close()

import cv2
import serial
import serial.tools.list_ports
import signal
import sys
from gpiozero import Button

# Constants
CAMERA_INDEX = 0
SERIAL_BAUD = 9600
ROI_HALF_EXTENT = 50
MIN_CONTOUR_AREA = 500
KEY_SAMPLE = ord('s')
KEY_DISABLE_TRACKING = ord('o')
KEY_QUIT = 27

# Global variables
cap = None
serial_port = None
tracking_enabled = False
min_HSV = None
max_HSV = None

def signal_handler(sig, frame):
    print('Exiting gracefully...')
    sys.exit(0)

def init_camera():
    global cap
    cap = cv2.VideoCapture(CAMERA_INDEX)
    if not cap.isOpened():
        raise Exception("Failed to open camera")
    ret, frame = cap.read()
    if not ret:
        raise Exception("Failed to read frame from camera")

def init_serial():
    global serial_port
    preferred_port = '/dev/ttyACM0'
    available_ports = [port.device for port in serial.tools.list_ports.comports()]
    if preferred_port in available_ports:
        port = preferred_port
    elif available_ports:
        port = available_ports[0]
        print(f"Preferred port {preferred_port} not available, using {port}")
    else:
        print("No serial ports available, running in serial-disabled mode")
        return

    try:
        serial_port = serial.Serial(port, SERIAL_BAUD, timeout=1)
    except serial.SerialException as e:
        print(f"Failed to open serial port {port}: {e}")
        serial_port = None

def sample_roi(frame):
    global min_HSV, max_HSV
    height, width, _ = frame.shape
    x, y = width // 2, height // 2
    roi = frame[y - ROI_HALF_EXTENT:y + ROI_HALF_EXTENT, x - ROI_HALF_EXTENT:x + ROI_HALF_EXTENT]
    hsv_roi = cv2.cvtColor(roi, cv2.COLOR_BGR2HSV)
    min_HSV = hsv_roi.min(axis=(0, 1))
    max_HSV = hsv_roi.max(axis=(0, 1))
    tracking_enabled = True

def track_ball(frame):
    if not tracking_enabled or min_HSV is None or max_HSV is None:
        return

    hsv_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    mask = cv2.inRange(hsv_frame, min_HSV, max_HSV)
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

    for contour in contours:
        if cv2.contourArea(contour) > MIN_CONTOUR_AREA:
            x, y, w, h = cv2.boundingRect(contour)
            cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)
            classify_position(x + w // 2, y + h // 2)

def classify_position(x, y):
    height, width, _ = cap.read()[1].shape
    center_x, center_y = width // 2, height // 2

    if x > center_x + ROI_HALF_EXTENT and y > center_y + ROI_HALF_EXTENT:
        send_command('1')
    elif x > center_x + ROI_HALF_EXTENT and y < center_y - ROI_HALF_EXTENT:
        send_command('2')
    elif x < center_x - ROI_HALF_EXTENT and y > center_y + ROI_HALF_EXTENT:
        send_command('3')
    elif x < center_x - ROI_HALF_EXTENT and y < center_y - ROI_HALF_EXTENT:
        send_command('4')
    else:
        send_command('5')

def send_command(command):
    if serial_port:
        try:
            serial_port.write(command.encode())
        except serial.SerialException as e:
            print(f"Failed to write to serial port: {e}")

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        init_camera()
        init_serial()

        while True:
            ret, frame = cap.read()
            if not ret:
                print("Failed to read frame from camera")
                break

            if cv2.waitKey(1) & 0xFF == KEY_SAMPLE:
                sample_roi(frame)

            if cv2.waitKey(1) & 0xFF == KEY_DISABLE_TRACKING:
                tracking_enabled = False

            if cv2.waitKey(1) & 0xFF == KEY_QUIT:
                break

            track_ball(frame)
            cv2.imshow('Frame', frame)

    finally:
        if cap:
            cap.release()
        if serial_port:
            serial_port.close()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

