import json
import os
import signal
import time
from gpiozero import DistanceSensor, OutputDevice
from gpiozero.exc import GPIODeviceError
import logging
from statistics import median

# Configuration defaults
DEFAULT_CONFIG = {
    "sensors": [
        {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0}
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log"
}

# Load or create configuration
def load_config(config_file="config.json"):
    if os.path.exists(config_file):
        try:
            with open(config_file, "r") as f:
                config = json.load(f)
        except (json.JSONDecodeError, IOError) as e:
            logging.error(f"Failed to load config: {e}")
            config = DEFAULT_CONFIG
    else:
        config = DEFAULT_CONFIG
        try:
            with open(config_file, "w") as f:
                json.dump(config, f, indent=4)
        except IOError as e:
            logging.error(f"Failed to save default config: {e}")
    return config

# Measure distance with a sensor
def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    try:
        sensor = DistanceSensor(echo=echo_pin, trigger=trigger_pin, max_distance=max_distance)
        distance = sensor.distance * 100  # Convert to cm
        distance += offset
        water_level = max_distance - distance
        return water_level
    except GPIODeviceError:
        return None

# Main monitoring loop
def monitor_water_level(config):
    sensors = [
        DistanceSensor(echo=s["echo_pin"], trigger=s["trigger_pin"], max_distance=s["max_distance"])
        for s in config["sensors"]
    ]
    last_alert_time = {s["trigger_pin"]: 0 for s in config["sensors"]}
    error_count = {s["trigger_pin"]: 0 for s in config["sensors"]}

    while True:
        readings = []
        for s in config["sensors"]:
            water_level = measure_distance(s["trigger_pin"], s["echo_pin"], s["offset"], s["max_distance"])
            if water_level is not None:
                readings.append(water_level)
                error_count[s["trigger_pin"]] = 0
            else:
                error_count[s["trigger_pin"]] += 1
                if error_count[s["trigger_pin"]] >= 5:
                    logging.warning(f"Sensor {s['trigger_pin']} is excluded due to 5 consecutive errors.")
                    continue

        if readings:
            median_level = median(readings)
            avg_level = sum(readings) / len(readings)
            logging.info(f"Median water level: {median_level:.2f} cm, Average water level: {avg_level:.2f} cm")

            if avg_level < config["alert_threshold_low"]:
                if time.time() - last_alert_time[s["trigger_pin"]] > config["alert_repeat_delay"]:
                    logging.warning(f"Low water level alert: {avg_level:.2f} cm")
                    last_alert_time[s["trigger_pin"]] = time.time()
            elif avg_level > config["alert_threshold_high"]:
                if time.time() - last_alert_time[s["trigger_pin"]] > config["alert_repeat_delay"]:
                    logging.warning(f"High water level alert: {avg_level:.2f} cm")
                    last_alert_time[s["trigger_pin"]] = time.time()
        else:
            logging.warning("No valid sensor readings.")

        time.sleep(5)

# Signal handler for clean shutdown
def signal_handler(sig, frame):
    logging.info("Shutting down water level monitor.")
    exit(0)

# Setup logging
logging.basicConfig(filename=config["log_file"], level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Load configuration
config = load_config()

# Initialize GPIO and start monitoring
try:
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    monitor_water_level(config)
except GPIODeviceError as e:
    logging.error(f"GPIO initialization failed: {e}")
    exit(0)
except Exception as e:
    logging.error(f"Unexpected error: {e}")
    exit(1)

