import os
import time
import signal
import logging
from gpiozero import PWMOutputDevice
from contextlib import contextmanager

# Configuration
FAN_PIN = 17
CPU_TEMP_PATH = '/sys/class/thermal/thermal_zone0/temp'
DEFAULT_PWM = 1.0
THRESHOLDS = [65.0, 55.0, 50.0, 45.0]
PWM_VALUES = [1.0, 0.8, 0.6, 0.4]

# Validate configuration
if len(THRESHOLDS) != len(PWM_VALUES):
    raise ValueError("THRESHOLDS and PWM_VALUES must have the same length.")
if not all(0.0 <= pwm <= 1.0 for pwm in PWM_VALUES):
    raise ValueError("PWM values must be between 0.0 and 1.0.")

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

@contextmanager
def fan_control(pin, default_pwm):
    fan = None
    try:
        fan = PWMOutputDevice(pin, frequency=1000)
        fan.value = default_pwm
        logging.info(f"Fan initialized with default PWM: {default_pwm}")
        yield fan
    except Exception as e:
        logging.error(f"Error initializing fan: {e}")
        exit(1)
    finally:
        if fan:
            try:
                fan.value = default_pwm
                fan.close()
                logging.info("Fan cleaned up and set to default PWM.")
            except Exception as e:
                logging.error(f"Error cleaning up fan: {e}")

def read_cpu_temperature():
    try:
        with open(CPU_TEMP_PATH, 'r') as file:
            temp_str = file.read().strip()
            return int(temp_str) / 1000.0
    except Exception as e:
        logging.error(f"Error reading CPU temperature: {e}")
        return None

def get_pwm_for_temperature(temp):
    for threshold, pwm in zip(THRESHOLDS, PWM_VALUES):
        if temp > threshold:
            return pwm
    return PWM_VALUES[-1]

def main():
    with fan_control(FAN_PIN, DEFAULT_PWM) as fan:
        try:
            while True:
                temp = read_cpu_temperature()
                if temp is not None:
                    pwm = get_pwm_for_temperature(temp)
                    try:
                        fan.value = pwm
                        logging.info(f"Current temperature: {temp:.1f}°C, Target PWM: {pwm}")
                    except Exception as e:
                        logging.error(f"Error setting fan PWM: {e}")
                time.sleep(5)
        except (KeyboardInterrupt, SystemExit):
            logging.info("Shutting down fan control.")

if __name__ == "__main__":
    main()

