def main():
    try:
        # Open the serial port
        with serial.Serial('/dev/rfcomm4', baudrate=38400, bytesize=serial.EIGHTBITS, parity=serial.PARITY_NONE, stopbits=serial.STOPBITS_ONE, timeout=1) as ser:
            print("Bluetooth serial connection opened on /dev/rfcomm4 at 38400 baud.")

            while True:
                try:
                    # Prompt user for input
                    user_input = input("Enter text (or 'q' to quit): ")

                    # Check for quit command
                    if user_input.lower() == 'q':
                        print("Exiting program.")
                        break

                    # Prepend 'X' and encode to UTF-8
                    message = f'X{user_input}'.encode('utf-8')

                    # Transmit the message
                    ser.write(message)
                    print(f"Transmitted {len(message)} bytes: {message.decode('utf-8')}", file=sys.stderr)

                except SerialException as e:
                    print(f"Error during serial write: {e}", file=sys.stderr)

    except SerialException as e:
        print(f"Failed to open serial port: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.", file=sys.stderr)
    finally:
        print("Exiting program.", file=sys.stderr)

import io
import logging
import signal
import threading
import numpy as np
import cv2
from picamera2 import Picamera2, Preview
from websocket_handler import WebSocketHandler  # Assume this is a user-provided class

class CameraStreamBuffer:
    def __init__(self, websocket_handler: WebSocketHandler):
        if not isinstance(websocket_handler, WebSocketHandler):
            raise TypeError("websocket_handler must be an instance of WebSocketHandler")
        self.websocket_handler = websocket_handler
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()
        self.logger = logging.getLogger(__name__)

    def write(self, data: bytes):
        with self.lock:
            self.buffer.write(data)
            if b'\xff\xd8' in data:
                self._broadcast_frame()

    def _broadcast_frame(self):
        with self.lock:
            self.buffer.seek(0)
            frame_data = self.buffer.getvalue()
            self.buffer.truncate(0)
            if self.websocket_handler.has_connections():
                self.websocket_handler.broadcast(frame_data)

    def flush(self):
        with self.lock:
            if self.buffer.tell() > 0:
                self._broadcast_frame()

class MotionDetectionBuffer:
    def __init__(self, detect_motion_function):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        self.detect_motion_function = detect_motion_function
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()
        self.previous_frame = None
        self.current_frame = None
        self.logger = logging.getLogger(__name__)

    def write(self, data: bytes):
        with self.lock:
            self.buffer.write(data)
            if b'\xff\xd8' in data:
                self._process_frame()

    def _process_frame(self):
        with self.lock:
            self.buffer.seek(0)
            frame_data = self.buffer.getvalue()
            self.buffer.truncate(0)
            self.current_frame = self._convert_to_opencv_frame(frame_data)
            if self.previous_frame is not None and self.current_frame is not None:
                self.detect_motion_function(self.previous_frame, self.current_frame)
            self.previous_frame = self.current_frame

    def _convert_to_opencv_frame(self, frame_data: bytes):
        try:
            np_array = np.frombuffer(frame_data, dtype=np.uint8)
            return cv2.imdecode(np_array, cv2.IMREAD_COLOR)
        except Exception as e:
            self.logger.error(f"Failed to decode frame: {e}")
            return None

    def flush(self):
        with self.lock:
            if self.buffer.tell() > 0:
                self._process_frame()

def detect_motion(previous_frame, current_frame):
    # Example motion detection logic
    gray_previous = cv2.cvtColor(previous_frame, cv2.COLOR_BGR2GRAY)
    gray_current = cv2.cvtColor(current_frame, cv2.COLOR_BGR2GRAY)
    diff = cv2.absdiff(gray_previous, gray_current)
    _, thresh = cv2.threshold(diff, 25, 255, cv2.THRESH_BINARY)
    contours, _ = cv2.findContours(thresh, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    if len(contours) > 0:
        print("Motion detected!")

def main():
    logging.basicConfig(level=logging.INFO)
    websocket_handler = WebSocketHandler()  # Initialize with actual implementation
    camera_stream_buffer = CameraStreamBuffer(websocket_handler)
    motion_detection_buffer = MotionDetectionBuffer(detect_motion)

    picam2 = Picamera2()
    config = picam2.create_video_configuration(resolution=(640, 480), fps=10, format="jpeg")
    picam2.configure(config)
    picam2.start_preview(Preview.NULL)
    picam2.start_recording(camera_stream_buffer, "jpeg")

    def signal_handler(sig, frame):
        picam2.stop_recording()
        camera_stream_buffer.flush()
        motion_detection_buffer.flush()
        exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            pass
    except KeyboardInterrupt:
        pass

if __name__ == "__main__":
    main()

