import smbus2
import signal
import sys

OLED_ADDRESS = 0x3C

def read_cpu_temperature():
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as file:
            temp_str = file.read().strip()
            temp_milli = int(temp_str)
            temp_celsius = temp_milli / 1000.0
            return temp_celsius
    except FileNotFoundError:
        print("Error: CPU temperature file not found.")
        return None
    except PermissionError:
        print("Error: Permission denied when reading CPU temperature.")
        return None

def initialize_i2c_bus():
    try:
        bus = smbus2.SMBus(1)
        bus.read_byte(OLED_ADDRESS)  # Attempt to read from the OLED to check connection
        return bus
    except smbus2.SMBusError as e:
        print(f"I2C bus initialization failed: {e}")
        return None

def main():
    bus = initialize_i2c_bus()
    if bus is None:
        return

    try:
        while True:
            temp_celsius = read_cpu_temperature()
            if temp_celsius is not None:
                print(f"CPU Temperature: {temp_celsius:.2f} °C")
            time.sleep(2)
    except KeyboardInterrupt:
        print("Exiting on keyboard interrupt.")
    finally:
        bus.close()
        print("I2C bus released.")

if __name__ == "__main__":
    main()

