import sys
import os
import time
import random
import logging
import argparse
from contextlib import contextmanager

# Setup logging
logging.basicConfig(filename='epaper_errors.log', level=logging.ERROR, format='%(asctime)s - %(message)s')

# Simulated GPIO class
class SimulatedGPIO:
    def __init__(self, pins):
        self.pins = pins

    def setup(self, pin, mode):
        pass

    def output(self, pin, value):
        pass

    def cleanup(self):
        pass

# Simulated display class
class SimulatedDisplay:
    def __init__(self, rst, dc, cs, busy):
        self.rst = rst
        self.dc = dc
        self.cs = cs
        self.busy = busy

    def init(self):
        time.sleep(random.uniform(0.5, 1.0))
        if random.random() < 0.1:
            logging.error("Display initialization failed")
            sys.exit(1)

    def update(self, product_id, product_name, inventory, price, barcode):
        logging.info(f"Updating display with: {product_id}, {product_name}, {inventory}, {price}, {barcode}")
        time.sleep(random.uniform(2, 4))

    def sleep(self):
        time.sleep(5)

# Check for low memory
def check_low_memory():
    try:
        os.urandom(1024 * 1024 * 100)  # Try to allocate 100MB
    except MemoryError:
        logging.warning("Low memory detected, skipping update")
        return True
    return False

# Context manager for GPIO cleanup
@contextmanager
def gpio_context(pins):
    try:
        gpio = SimulatedGPIO(pins)
        yield gpio
    finally:
        gpio.cleanup()

def main():
    parser = argparse.ArgumentParser(description="Warehouse Shelf Label System Simulation")
    parser.add_argument('--rst', type=int, default=17, help='RST pin number')
    parser.add_argument('--dc', type=int, default=25, help='DC pin number')
    parser.add_argument('--cs', type=int, default=8, help='CS pin number')
    parser.add_argument('--busy', type=int, default=24, help='BUSY pin number')
    parser.add_argument('--product_id', type=str, default='SKU-001', help='Product ID')
    parser.add_argument('--product_name', type=str, default='Example Product', help='Product Name')
    parser.add_argument('--inventory', type=int, default=50, help='Initial Inventory')
    parser.add_argument('--price', type=float, default=25.99, help='Initial Price')

    args = parser.parse_args()

    pins = [args.rst, args.dc, args.cs, args.busy]
    display = SimulatedDisplay(args.rst, args.dc, args.cs, args.busy)

    try:
        with gpio_context(pins):
            display.init()
            while True:
                if check_low_memory():
                    continue

                display.update(args.product_id, args.product_name, args.inventory, args.price, "1234567890123")

                args.inventory -= random.randint(1, 5)
                if args.inventory < 0:
                    args.inventory = 0

                if random.random() < 0.33:
                    args.price += random.uniform(-1.00, 1.00)
                    args.price = max(0.01, args.price)  # Ensure price is not negative

                display.sleep()
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received, cleaning up")
    except Exception as e:
        logging.error(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

import RPi.GPIO as GPIO
import time

# Constants
TRIG_PIN = 5
ECHO_PIN = 6
TIMEOUT = 1  # seconds
SAMPLES = 10
DELAY = 0.3  # seconds
DISTANCE_THRESHOLD = 5  # cm

# Setup GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(TRIG_PIN, GPIO.OUT)
GPIO.setup(ECHO_PIN, GPIO.IN)

def measure_distance():
    GPIO.output(TRIG_PIN, False)
    time.sleep(0.2)
    GPIO.output(TRIG_PIN, True)
    time.sleep(0.00001)
    GPIO.output(TRIG_PIN, False)

    start_time = time.time()
    while GPIO.input(ECHO_PIN) == 0:
        if time.time() - start_time > TIMEOUT:
            return None
        pulse_start = time.time()

    while GPIO.input(ECHO_PIN) == 1:
        if time.time() - start_time > TIMEOUT:
            return None
        pulse_end = time.time()

    pulse_duration = pulse_end - pulse_start
    distance = pulse_duration * 17150  # Speed of sound in cm/s * 100 cm/m * 2 (round trip)
    return distance

def classify_gesture(distances):
    if len(distances) < 2:
        return None

    change = distances[-1] - distances[-2]
    if change > DISTANCE_THRESHOLD:
        return 'swipe_in'
    elif change < -DISTANCE_THRESHOLD:
        return 'swipe_out'
    else:
        return 'hold'

def main():
    distances = []
    try:
        for _ in range(SAMPLES):
            distance = measure_distance()
            if distance is not None:
                distances.append(distance)
                gesture = classify_gesture(distances)
                if gesture:
                    print(f"Detected gesture: {gesture}")
            else:
                print("Timeout: No echo received")
            time.sleep(DELAY)
    except KeyboardInterrupt:
        print("Program interrupted by user")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

import time
import logging
import subprocess
from gpiozero import InputDevice
from datetime import datetime

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# GPIO pins
LIGHT_PIN = 17
TEMP_PIN = 4

# Initialize GPIO devices
light_sensor = InputDevice(LIGHT_PIN, pull_up=False)
temp_sensor = InputDevice(TEMP_PIN, pull_up=False)

def simulate_light_level():
    try:
        current_hour = datetime.now().hour
        if 6 <= current_hour < 18:
            return random.randint(600, 1000)
        else:
            return random.randint(100, 300)
    except Exception as e:
        logging.error(f"Error simulating light level: {e}")
        return 0

def simulate_temperature():
    try:
        return random.uniform(20, 30)
    except Exception as e:
        logging.error(f"Error simulating temperature: {e}")
        return None

def simulate_voltage_current(light_level):
    try:
        if light_level > 300:
            return random.uniform(11.5, 12.5), random.uniform(1.5, 2.5)
        else:
            return random.uniform(10.0, 11.0), random.uniform(0.5, 1.0)
    except Exception as e:
        logging.error(f"Error simulating voltage and current: {e}")
        return None, None

def read_pi_temperature():
    try:
        result = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, text=True, timeout=1)
        if result.returncode == 0:
            temp_str = result.stdout.strip().split('=')[1].replace('\'C', '')
            return float(temp_str)
        else:
            logging.warning("Failed to read Pi temperature with vcgencmd")
            return None
    except subprocess.TimeoutExpired:
        logging.warning("Timeout expired while reading Pi temperature")
        return None
    except Exception as e:
        logging.error(f"Error reading Pi temperature: {e}")
        return None

def log_cycle(light_level, temperature, voltage, current, pi_temp):
    try:
        logging.info(f"Light: {light_level} lux, Temperature: {temperature} °C, Voltage: {voltage} V, Current: {current} A, Pi Temperature: {pi_temp if pi_temp is not None else 'N/A'} °C")
    except Exception as e:
        logging.error(f"Error logging cycle: {e}")

def main():
    try:
        while True:
            light_level = simulate_light_level()
            temperature = simulate_temperature()
            voltage, current = simulate_voltage_current(light_level)
            pi_temp = read_pi_temperature()

            if light_level < 300:
                logging.warning("WARNING: Possible solar panel performance issues detected.")
            if temperature > 35:
                logging.warning("WARNING: Simulated cooling system activated.")
            if pi_temp is not None and pi_temp > 75:
                logging.critical("CRITICAL: Simulated system shutdown due to high Pi temperature.")

            log_cycle(light_level, temperature, voltage, current, pi_temp)
            time.sleep(5)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    finally:
        light_sensor.close()
        temp_sensor.close()
        logging.info("GPIO devices closed.")

if __name__ == '__main__':
    main()

