# Configuration for the serial port
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 115200
TIMEOUT = 1.0

# Serial port object
ser = None

def open_serial_port():
    global ser
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Serial port {SERIAL_PORT} opened successfully.")
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}")
        sys.exit(1)

def read_and_parse_temperature():
    try:
        if ser.in_waiting > 0:
            line = ser.readline().decode('ascii', errors='ignore').strip()
            # Find the first floating-point number in the line
            parts = line.split()
            for part in parts:
                try:
                    temperature = float(part)
                    print(f"Temperature: {temperature:.1f} C")
                    return
                except ValueError:
                    continue
            print("No valid temperature found in the data.")
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
    except ValueError as e:
        print(f"Malformed data received: {e}")

def close_serial_port():
    global ser
    if ser and ser.is_open:
        ser.close()
        print(f"Serial port {SERIAL_PORT} closed.")

def signal_handler(sig, frame):
    print("\nProgram terminated by user.")
    close_serial_port()
    sys.exit(0)

# Register the signal handler for graceful termination
signal.signal(signal.SIGINT, signal_handler)

# Main program loop
if __name__ == "__main__":
    open_serial_port()
    try:
        while True:
            read_and_parse_temperature()
            time.sleep(0.5)
    except KeyboardInterrupt:
        pass
    finally:
        close_serial_port()

