import smbus2
import time
import logging

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DHT20:
    I2C_BUS = 1
    I2C_ADDRESS = 0x38
    STATUS_REGISTER = 0x71
    COMMAND_REGISTER = 0xAC
    MEASURE_COMMAND = [0x33, 0x00]
    CRC_POLYNOMIAL = 0x31
    CRC_INIT = 0xFF

    def __init__(self):
        self.bus = None
        self.open_i2c_bus()

    def open_i2c_bus(self):
        try:
            self.bus = smbus2.SMBus(self.I2C_BUS)
            time.sleep(0.5)  # Wait for power stabilization
            status = self.bus.read_byte_data(self.I2C_ADDRESS, self.STATUS_REGISTER)
            if (status & 0x18) != 0x18:
                logging.error("Status check failed: 0x{:02X}".format(status))
                self.close_i2c_bus()
                return False
            return True
        except Exception as e:
            logging.error("Failed to open I2C bus: {}".format(e))
            self.close_i2c_bus()
            return False

    def close_i2c_bus(self):
        if self.bus:
            self.bus.close()
            self.bus = None

    def calculate_crc8(self, data, polynomial, init):
        crc = init
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ polynomial
                else:
                    crc <<= 1
                crc &= 0xFF
        return crc

    def get_temperature_and_humidity(self):
        attempts = 0
        while attempts < 5:
            try:
                self.bus.write_i2c_block_data(self.I2C_ADDRESS, self.COMMAND_REGISTER, self.MEASURE_COMMAND)
                start_time = time.time()
                while True:
                    status = self.bus.read_byte_data(self.I2C_ADDRESS, self.STATUS_REGISTER)
                    if not (status & 0x80):
                        break
                    if time.time() - start_time > 0.1:
                        logging.warning("Timeout waiting for measurement to complete, retrying...")
                        break
                else:
                    data = self.bus.read_i2c_block_data(self.I2C_ADDRESS, self.STATUS_REGISTER, 7)
                    raw_humidity = (data[1] << 16) | (data[2] << 8) | data[3]
                    raw_temperature = ((data[3] & 0xF0) << 12) | (data[4] << 4) | (data[5] >> 4)
                    crc = data[6]

                    calculated_crc = self.calculate_crc8(data[:6], self.CRC_POLYNOMIAL, self.CRC_INIT)
