    I2C_BUS = 1
    I2C_ADDRESS = 0x38
    STATUS_REGISTER = 0x71
    COMMAND_REGISTER = 0xAC
    MEASURE_COMMAND = [0x33, 0x00]
    CRC_POLYNOMIAL = 0x31
    CRC_INIT = 0xFF

    def __init__(self):
        self.bus = None
        self.open_i2c_bus()

    def open_i2c_bus(self):
        try:
            self.bus = smbus2.SMBus(self.I2C_BUS)
            time.sleep(0.5)  # Wait for power stabilization
            status = self.bus.read_byte_data(self.I2C_ADDRESS, self.STATUS_REGISTER)
            if (status & 0x18) != 0x18:
                logging.error("Status check failed: 0x{:02X}".format(status))
