import serial
import csv
import time
import sys
from datetime import datetime

def celsius_to_fahrenheit(celsius):
    return celsius * 9/5 + 32

def log_temperature(celsius, fahrenheit):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    with open('temperature_log.csv', 'a', newline='') as csvfile:
        writer = csv.writer(csvfile)
        if csvfile.tell() == 0:  # Check if file is empty
            writer.writerow(['timestamp', 'celsius', 'fahrenheit'])
        writer.writerow([timestamp, celsius, fahrenheit])

def main():
    try:
        ser = serial.Serial('/dev/ttyACM0', 115200, timeout=1)
    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            try:
                line = ser.readline().decode('ascii').strip()
                try:
                    celsius = float(line)
                    fahrenheit = celsius_to_fahrenheit(celsius)
                    log_temperature(celsius, fahrenheit)
                except ValueError:
                    print(f"Warning: Malformed temperature data '{line}'", file=sys.stderr)
            except serial.SerialTimeoutException:
                pass  # Timeout occurred, continue to next iteration
    except KeyboardInterrupt:
        print("Exiting gracefully...")
    finally:
        ser.close()

if __name__ == "__main__":
    main()

