def read_dht22():
    def pulse(pin, duration):
        GPIO.output(pin, GPIO.LOW)
        time.sleep(duration / 1000000)
        GPIO.output(pin, GPIO.HIGH)

    def read_bit(pin):
        while GPIO.input(pin) == GPIO.LOW:
            pass
        start = time.time()
        while GPIO.input(pin) == GPIO.HIGH:
            if (time.time() - start) > 0.00008:
                return 0
        while GPIO.input(pin) == GPIO.LOW:
            if (time.time() - start) > 0.0002:
                return 1
        return 0

    def read_byte(pin):
        byte = 0
        for i in range(8):
            byte = (byte << 1) | read_bit(pin)
        return byte

    def read_dht22_data():
        GPIO.output(DHT_PIN, GPIO.HIGH)
        time.sleep(0.1)
        pulse(DHT_PIN, 18000)
        GPIO.setup(DHT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        if GPIO.input(DHT_PIN) != GPIO.LOW:
            return None
        time.sleep(0.00008)
        if GPIO.input(DHT_PIN) != GPIO.HIGH:
            return None
        time.sleep(0.00008)

        data = []
        for _ in range(40):
            data.append(read_bit(DHT_PIN))

        GPIO.setup(DHT_PIN, GPIO.OUT)
        GPIO.output(DHT_PIN, GPIO.HIGH)

        humidity_int = (data[0] << 8) + data[1]
        humidity_dec = data[2]
        temperature_int = (data[3] << 8) + data[4]
        temperature_dec = data[5]
        checksum = data[6]

        if checksum != ((humidity_int + humidity_dec + temperature_int + temperature_dec) & 0xFF):
            return None

        return humidity_int, humidity_dec, temperature_int, temperature_dec

    for attempt in range(3):
        data = read_dht22_data()
        if data:
            humidity_int, humidity_dec, temperature_int, temperature_dec = data
            humidity = humidity_int + humidity_dec / 10.0
            temperature = temperature_int + temperature_dec / 10.0
            return humidity, temperature
        time.sleep(2)
    return None

try:
    while True:
        result = read_dht22()
        if result:
            humidity, temperature = result
            print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
        else:
            print("Failed to read from DHT22 sensor.")
        time.sleep(5)
except KeyboardInterrupt:
