import time
import board
import adafruit_dht

# Initialize the DHT22 sensor on GPIO22 (BCM numbering)
dht_device = adafruit_dht.DHT22(board.D22)

def read_sensor():
    """Read temperature and humidity from the DHT22 sensor with retry mechanism."""
    retries = 2
    for attempt in range(retries + 1):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as e:
            print(f"Runtime error reading sensor: {e}")
        except adafruit_dht.ChecksumError:
            print("Checksum error reading sensor.")
        except adafruit_dht.UnavailableError:
            print("Sensor is unavailable.")
        if attempt < retries:
            time.sleep(0.1)
    return None, None

def main():
    """Main loop to continuously read sensor data."""
    try:
        print("Initializing sensor...")
        time.sleep(1)  # Let the sensor stabilize
        while True:
            temperature, humidity = read_sensor()
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
            else:
                print("Failed to read sensor data.")
            time.sleep(3)  # Read sensor data every 3 seconds
    except KeyboardInterrupt:
        print("Shutting down sensor...")
    finally:
        dht_device.exit()
        print("Sensor resources released.")

if __name__ == "__main__":
