import time
import logging
from contextlib import contextmanager

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DHT20:
    I2C_ADDRESS = 0x38
    STATUS_REGISTER = 0x71
    MEASURE_COMMAND = [0x33, 0x00]
    CRC_POLYNOMIAL = 0x31
    CRC_INIT = 0xFF

    def __init__(self, bus_number=1):
        self.bus_number = bus_number
        self.bus = None
        self.last_measurement_time = 0
        self.last_temperature = None
        self.last_humidity = None

    def crc8(self, data, polynomial=CRC_POLYNOMIAL, init=CRC_INIT):
        crc = init
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ polynomial
                else:
                    crc <<= 1
                crc &= 0xFF
        return crc

    def open_bus(self):
        try:
            self.bus = smbus2.SMBus(self.bus_number)
            time.sleep(0.5)
            status = self.bus.read_byte_data(self.I2C_ADDRESS, self.STATUS_REGISTER)
            if (status & 0x18) != 0x18:
                logging.error("Status register check failed: 0x{:02X}".format(status))
                return False
            return True
        except OSError as e:
            logging.error("Failed to open I2C bus: {}".format(e))
            return False

    def trigger_measurement(self):
        try:
            self.bus.write_i2c_block_data(self.I2C_ADDRESS, 0xAC, self.MEASURE_COMMAND)
        except OSError as e:
            logging.warning("Failed to trigger measurement: {}".format(e))
            return False
        return True

    def wait_for_idle(self):
        for _ in range(10):
            try:
                status = self.bus.read_byte_data(self.I2C_ADDRESS, self.STATUS_REGISTER)
                if status & 0x80 == 0:
                    return True
            except OSError as e:
                logging.warning("Failed to read status register: {}".format(e))
            time.sleep(0.08)
        return False

    def read_measurement(self):
        try:
            data = self.bus.read_i2c_block_data(self.I2C_ADDRESS, self.STATUS_REGISTER, 7)
            if self.crc8(data[:6]) != data[6]:
                logging.warning("CRC mismatch")
                return None, None
            humidity_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
            temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
            humidity = humidity_raw / (2**20) * 100
            temperature = temperature_raw / (2**19) * 200 - 50
            return humidity, temperature
        except OSError as e:
            logging.warning("Failed to read measurement data: {}".format(e))
            return None, None

    def get_temperature_and_humidity(self):
        current_time = time.time()
        if current_time - self.last_measurement_time < 2:
            logging.info("Returning cached result due to minimum interval not met.")
            return self.last_temperature, self.last_humidity

        for attempt in range(5):
            if not self.trigger_measurement():
                continue
            if not self.wait_for_idle():
                continue
            humidity, temperature = self.read_measurement()
            if humidity is not None and temperature is not None:
                self.last_temperature = temperature
                self.last_humidity = humidity
                self.last_measurement_time = current_time
                return humidity, temperature
            time.sleep(0.01)
        logging.error("All measurement attempts failed.")
        return None, None, True

    def close(self):
        if self.bus:
            self.bus.close()
            self.bus = None

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

def demo():
    dht20 = DHT20()
    if not dht20.open_bus():
        print("Failed to initialize DHT20 sensor. Exiting.")
        return 0

    try:
        while True:
            humidity, temperature, error = dht20.get_temperature_and_humidity()
            if error:
                print("Measurement error occurred.")
                break
            if humidity is not None and temperature is not None:
                print(f"Temperature: {temperature:.2f} °C, Humidity: {humidity:.2f} %")
            time.sleep(1)
    except (KeyboardInterrupt, SystemExit):
        logging.info("Demo interrupted by user.")
    finally:
        dht20.close()

if __name__ == "__main__":
    demo()

