import RPi.GPIO as GPIO
import threading
import time
import signal
import sys
import os

# Mock implementation of DOG class for demonstration purposes
class DOG:
    def send(self, data_string):
        print(f"Sending data: {data_string}")

    def receive(self):
        # Simulate receiving data
        return "Received data"

# Global variables
log_file = None
log_thread = None
running = False

def signal_handler(sig, frame):
    global running
    running = False
    if log_thread and log_thread.is_alive():
        log_thread.join()
    GPIO.cleanup()
    print("Server stopped and GPIO cleaned up.")
    sys.exit(0)

def log_data():
    global running
    while running:
        try:
            data = DOG().receive()
            if log_file:
                with open(log_file, 'a') as f:
                    f.write(data + '\n')
        except Exception as e:
            print(f"Error in log_data: {e}")
        time.sleep(0.1)

def start_server(filename):
    global log_file, log_thread, running
    if running:
        print("Server is already running.")
        return
    try:
        log_file = filename
        running = True
        log_thread = threading.Thread(target=log_data)
        log_thread.start()
        print(f"Server started and logging to {filename}.")
    except Exception as e:
        print(f"Error starting server: {e}")

def stop_server():
    global running
    if not running:
        print("Server is not running.")
        return
    running = False
    if log_thread and log_thread.is_alive():
        log_thread.join()
    print("Server stopped.")

def display_log():
    global log_file
    if not log_file:
        print("No log file specified.")
        return
    try:
        with open(log_file, 'r') as f:
            print(f.read())
    except FileNotFoundError:
        print("Log file not found.")
    except Exception as e:
        print(f"Error reading log file: {e}")

def send_data(data):
    try:
        DOG().send(data)
        print(f"Data sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")

def write_to_log(data):
    global log_file
    if not log_file:
        print("No log file specified.")
        return
    try:
        with open(log_file, 'a') as f:
            f.write(data + '\n')
        print(f"Data written to log: {data}")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def help_command(command=None):
    if command:
        if command == "start":
            print("start <filename>: Creates a file and starts the logging thread.")
        elif command == "stop":
            print("stop: Stops the server and the receive thread.")
        elif command == "help":
            print("help [command]: Displays help.")
        elif command == "display":
            print("display: Prints the contents of the log file.")
        elif command == "send":
            print("send <data>: Sends data using DOG.send().")
        elif command == "write":
            print("write <data>: Writes data directly to the log file with a newline character.")
        elif command == "exit":
            print("exit: Stops the server, cleans up GPIO, and exits.")
        else:
            print(f"Unknown command: {command}")
    else:
        print("Available commands:")
        print("start <filename>")
        print("stop")
        print("help [command]")
        print("display")
        print("send <data>")
        print("write <data>")
        print("exit")

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    while True:
        command = input("Enter command: ").strip().split()
        if not command:
            continue

        if command[0] == "start":
            if len(command) != 2:
                print("Usage: start <filename>")
            else:
                start_server(command[1])
        elif command[0] == "stop":
            stop_server()
        elif command[0] == "help":
            if len(command) > 1:
                help_command(command[1])
            else:
                help_command()
        elif command[0] == "display":
            display_log()
        elif command[0] == "send":
            if len(command) != 2:
                print("Usage: send <data>")
            else:
                send_data(command[1])
        elif command[0] == "write":
            if len(command) != 2:
                print("Usage: write <data>")
            else:
                write_to_log(command[1])
        elif command[0] == "exit":
            stop_server()
            GPIO.cleanup()
            print("Exiting server.")
            break
        else:
            print(f"Unknown command: {command[0]}")

if __name__ == "__main__":
    try:
        GPIO.setmode(GPIO.BCM)
        main()
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
    finally:
        GPIO.cleanup()
