import RPi.GPIO as GPIO
import time

# Constants
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6
SAMPLE_INTERVAL = 0.5  # seconds
NUM_SAMPLES = 10

# Setup GPIO
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN)
    GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN)
except Exception as e:
    print(f"Error setting up GPIO: {e}")
    GPIO.cleanup()
    exit(1)

def read_sensors():
    try:
        left_sensor = GPIO.input(LEFT_SENSOR_PIN)
        right_sensor = GPIO.input(RIGHT_SENSOR_PIN)
        return left_sensor, right_sensor
    except Exception as e:
        print(f"Error reading sensors: {e}")
        return None, None

def decide_steering(left_sensor, right_sensor):
    if left_sensor == 0 and right_sensor == 0:
        return "forward"
    elif left_sensor == 1 and right_sensor == 0:
        return "turn-left"
    elif left_sensor == 0 and right_sensor == 1:
        return "turn-right"
    else:
        return "search"

def main():
    try:
        for _ in range(NUM_SAMPLES):
            left_sensor, right_sensor = read_sensors()
            if left_sensor is None or right_sensor is None:
                continue  # Skip this iteration if there was an error reading sensors

            steering = decide_steering(left_sensor, right_sensor)
            print(f"Sample: Left={left_sensor}, Right={right_sensor}, Steering={steering}")
            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        GPIO.cleanup()
        print("GPIO cleaned up.")

if __name__ == "__main__":
    main()

