import logging
import signal
import time
import zmq
from gpiozero import PWMOutputDevice, OutputDevice, DeviceClosed
from gpiozero.exc import GPIODeviceError

class PIDHandler:
    def __init__(self, pwm=True):
        self.pwm = pwm
        self.global_err_state = False
        self.last_msg = time.time()
        self.setup_gpio()
        self.setup_logging()
        self.setup_zmq()
        self.setup_signal_handler()

    def setup_gpio(self):
        try:
            if self.pwm:
                self.error_output = PWMOutputDevice(pin=12, frequency=1000, initial_value=0.0)
            else:
                self.error_output = OutputDevice(pin=10, initial_value=False)
        except (GPIODeviceError, DeviceClosed) as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            raise

    def setup_logging(self):
        logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

    def setup_zmq(self):
        self.context = zmq.Context()
        self.socket = self.context.socket(zmq.SUB)
        self.socket.connect("tcp://localhost:5555")
        self.socket.setsockopt_string(zmq.SUBSCRIBE, "")

    def setup_signal_handler(self):
        signal.signal(signal.SIGINT, self.cleanup)
        signal.signal(signal.SIGTERM, self.cleanup)

    def update_error_output(self):
        if self.pwm:
            self.error_output.value = 1.0 if self.global_err_state else 0.0
        else:
            self.error_output.value = self.global_err_state

    def set_error_output(self, state: bool):
        self.global_err_state = state
        self.update_error_output()

    def handle_message(self):
        try:
            message = self.socket.recv(zmq.NOBLOCK)
            self.last_msg = time.time()
            self.process_message(message)
        except zmq.Again:
            if time.time() - self.last_msg > 20:
                self.set_error_output(True)
        except Exception as e:
            logging.error(f"Error handling message: {e}")

    def process_message(self, message):
        # Placeholder for message processing logic
        logging.info(f"Received message: {message}")

    def cleanup(self, signum, frame):
        logging.info("Cleaning up resources...")
        self.error_output.close()
        self.socket.close()
        self.context.term()
        logging.info("Resources cleaned up.")
        exit(0)

# Example usage
if __name__ == "__main__":
    pid_handler = PIDHandler(pwm=True)
    try:
        while True:
            pid_handler.handle_message()
            time.sleep(1)
    except KeyboardInterrupt:
        pass

