import time
import board
import busio
import adafruit_fingerprint
from gpiozero import CPUTemperature
from adafruit_circuitpython_adafruit_fingerprint import Adafruit_Fingerprint
import paho.mqtt.client as mqtt

# Initialize I2C bus
i2c_bus = busio.I2C(board.SCL, board.SDA)

# Initialize fingerprint sensor
fingerprint_sensor = None

def initialize_fingerprint_sensor():
    global fingerprint_sensor
    try:
        fingerprint_sensor = Adafruit_Fingerprint(i2c_bus)
        print("Fingerprint sensor initialized successfully.")
    except ValueError as e:
        print(f"ValueError: {e}. The I2C bus might be locked. Please check the I2C bus and try again.")
    except RuntimeError as e:
        print(f"RuntimeError: {e}. The fingerprint sensor might be absent or unresponsive. Please check the connection and try again.")

def authenticate_fingerprint():
    while True:
        try:
            if fingerprint_sensor.get_image() == adafruit_fingerprint.OK:
                print("Fingerprint image acquired.")
                if fingerprint_sensor.image_2_tz(1) == adafruit_fingerprint.OK:
                    print("Template created.")
                    if fingerprint_sensor.finger_search() == adafruit_fingerprint.OK:
                        print(f"Access Granted. Matched ID: {fingerprint_sensor.finger_id}, Confidence: {fingerprint_sensor.confidence}")
                    else:
                        print("Access Denied.")
                else:
                    print("Failed to create template.")
            else:
                print("No finger detected.")
        except RuntimeError as e:
            print(f"RuntimeError: {e}. Retrying...")
        except Exception as e:
            print(f"Unexpected error: {e}. Retrying...")
        time.sleep(1)

def on_connect(client, userdata, flags, rc):
    print(f"Connected with result code {rc}")

def on_message(client, userdata, msg):
    print(f"Received message '{msg.payload.decode()}' on topic '{msg.topic}'")

def main():
    initialize_fingerprint_sensor()
    if fingerprint_sensor is None:
        print("Failed to initialize fingerprint sensor. Exiting.")
        return

    # Initialize MQTT client
    client = mqtt.Client()
    client.on_connect = on_connect
    client.on_message = on_message

    # Connect to MQTT broker
    client.connect("mqtt.eclipse.org", 1883, 60)

    # Start the MQTT loop in a separate thread
    client.loop_start()

    try:
        authenticate_fingerprint()
    except KeyboardInterrupt:
        print("Authentication loop interrupted by user.")
    finally:
        client.loop_stop()
        client.disconnect()
        print("MQTT client disconnected.")
        print("Exiting cleanly.")

if __name__ == "__main__":
    main()

