import pigpio
import time
from typing import Optional

class PiGpioConnectionError(Exception):
    """Custom exception for pigpio connection errors."""
    pass

class OutputPin:
    def __init__(self, pin_number: int, initial_value: int):
        if not (0 <= pin_number <= 31):
            raise ValueError("Pin number must be between 0 and 31.")
        if initial_value not in (0, 1):
            raise ValueError("Initial value must be 0 or 1.")

        self.pin_number = pin_number
        self.pi: Optional[pigpio.pi] = None

        try:
            self.pi = pigpio.pi()
            if not self.pi.connected:
                raise PiGpioConnectionError("Could not connect to the pigpio daemon.")
            self.pi.set_mode(pin_number, pigpio.OUTPUT)
            self.pi.write(pin_number, initial_value)
        except pigpio.error as e:
            self.shutdown()
            raise RuntimeError(f"Error initializing OutputPin: {e}") from e

    def set_value(self, value: int):
        if value not in (0, 1):
            raise ValueError("Value must be 0 or 1.")
        try:
            self.pi.write(self.pin_number, value)
        except (AttributeError, pigpio.error) as e:
            raise RuntimeError(f"Error setting pin value: {e}") from e

    def shutdown(self):
        if self.pi:
            try:
                self.pi.set_mode(self.pin_number, pigpio.INPUT)
                self.pi.stop()
            except pigpio.error as e:
                print(f"Warning: Error shutting down OutputPin: {e}")
            finally:
                self.pi = None

if __name__ == '__main__':
    try:
        pin = OutputPin(17, 0)
        for _ in range(10):
            pin.set_value(1)
            time.sleep(0.5)
            pin.set_value(0)
            time.sleep(0.5)
    finally:
        pin.shutdown()

