import gpiozero
from gpiozero import Button
from threading import Event

class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback=None):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.counter = 0
        self.clk_state = False
        self.dt_state = False
        self.stop_event = Event()

        if self.callback is not None and not callable(self.callback):
            raise ValueError("Callback must be a callable function.")

        self.clk = Button(clk_pin, pull_up=True, bounce_time=0.005)
        self.dt = Button(dt_pin, pull_up=True, bounce_time=0.005)

        self.clk.when_pressed = self._handle_clk_edge
        self.clk.when_released = self._handle_clk_edge

    def _handle_clk_edge(self):
        if self.stop_event.is_set():
            return

        current_clk_state = self.clk.is_pressed
        current_dt_state = self.dt.is_pressed

        if current_clk_state != self.clk_state:
            self.clk_state = current_clk_state
            if current_clk_state:
                if current_dt_state != self.dt_state:
                    self.counter += 1
                else:
                    self.counter -= 1
                self.dt_state = current_dt_state
                self._execute_callback()

    def _execute_callback(self):
        if self.callback is not None:
            try:
                self.callback(self.counter)
            except Exception as e:
                print(f"Error executing callback: {e}")

    def cleanup(self):
        self.stop_event.set()
        self.clk.close()
        self.dt.close()

if __name__ == "__main__":
    def on_rotation(counter):
        print(f"Counter: {counter}")

    encoder = RotaryEncoder(clk_pin=17, dt_pin=18, callback=on_rotation)

    try:
        while True:
            pass
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        encoder.cleanup()

