# Initialize I2C bus
i2c = None
try:
    i2c = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    logging.error(f"Failed to initialize I2C bus: {e}")
    exit(1)

# Initialize TCS34725 sensor
sensor = None
try:
    sensor = adafruit_tcs34725.TCS34725(i2c, integration_time=adafruit_tcs34725.INTEGRATION_TIME_50MS, gain=adafruit_tcs34725.GAIN_4X)
except ValueError as e:
    logging.error(f"Sensor not found or I2C bus error: {e}")
    exit(1)

def get_sensor_color_data():
    try:
        r, g, b, c = sensor.color_rgb_bytes
        return (r, g, b, c)
    except Exception as e:
        logging.error(f"Failed to read sensor data: {e}")
        return (0, 0, 0, 0)

def find_dominant_image_color(image_path):
    try:
        with Image.open(image_path) as img:
            img = img.resize((100, 100))
            colors = img.getcolors(256)
            if colors:
                dominant_color = max(colors, key=lambda x: x[0])[1]
                return dominant_color
            else:
                return (0, 0, 0)
    except FileNotFoundError:
        logging.error(f"File not found: {image_path}")
        return (0, 0, 0)
    except Exception as e:
        logging.error(f"Error processing image: {e}")
        return (0, 0, 0)

def cleanup():
    global i2c
    if i2c:
        i2c.deinit()
        logging.info("I2C bus deinitialized")

def signal_handler(sig, frame):
