import RPi.GPIO as GPIO
import time
from datetime import datetime

# Constants
PIR_PIN = 4
FEEDING_TIMES = [(7, 8), (18, 19)]  # 7:00-8:00 AM and 6:00-7:00 PM
DEBOUNCE_DELAY = 60  # seconds

# Setup GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

# Global state
last_feed_time = None

def is_feeding_time(now):
    hour = now.hour
    for start, end in FEEDING_TIMES:
        if start <= hour < end:
            return True
    return False

def log_event(message):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"{timestamp} - {message}")

def main():
    global last_feed_time
    try:
        while True:
            if GPIO.input(PIR_PIN) == GPIO.HIGH:
                now = datetime.now()
                log_event("Motion detected")
                if is_feeding_time(now):
                    if last_feed_time is None or (now - last_feed_time).total_seconds() >= DEBOUNCE_DELAY:
                        log_event("Feeding initiated")
                        last_feed_time = now
                    else:
                        log_event("Not feeding time or recently fed")
                else:
                    log_event("Not feeding time or recently fed")
            time.sleep(1)
    except KeyboardInterrupt:
        log_event("Exiting program...")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

