import atexit
import signal
import logging
import time
from adafruit_motorkit import MotorKit
from adafruit_motor import stepper

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DCMotorHATExtra(MotorKit):
    def __init__(self, address=0x60, i2c_bus=1, freq=60):
        try:
            super().__init__(address=address, i2c_bus=i2c_bus)
            self.set_pwm_freq(freq)
            logging.info("DCMotorHATExtra initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize DCMotorHATExtra: {e}")
            raise

    def set_pwm_freq(self, freq):
        try:
            super().frequency = freq
            logging.info(f"Set PWM frequency to {freq} Hz.")
        except Exception as e:
            logging.error(f"Failed to set PWM frequency: {e}")
            raise

    def get_pwm_freq(self):
        try:
            return super().frequency
        except Exception as e:
            logging.error(f"Failed to get PWM frequency: {e}")
            raise

    def release_all_motors(self):
        for i in range(1, 5):
            try:
                self.motor[i].throttle = 0
                logging.info(f"Released motor {i}.")
            except Exception as e:
                logging.error(f"Failed to release motor {i}: {e}")

    def __del__(self):
        self.release_all_motors()

def signal_handler(sig, frame):
    logging.info("Received signal to exit.")
    atexit._run_exitfuncs()
    exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

atexit.register(DCMotorHATExtra.release_all_motors)

class DCMotor:
    def __init__(self, hat, motor_num, freq=None, invert=False):
        if not (1 <= motor_num <= 4):
            raise ValueError("Motor number must be between 1 and 4.")
