import pigpio
import time

class MotorError(Exception):
    """Custom exception for Motor class errors."""
    pass

class Motor:
    def __init__(self, pi, pin):
        if not isinstance(pi, pigpio.pi) or not pi.connected:
            raise MotorError("Invalid or disconnected pigpio.pi instance.")

        self.pi = pi
        self.pin = pin
        self.pi.set_mode(pin, pigpio.OUTPUT)
        self.pi.set_PWM_frequency(pin, 1000)
        self.pi.set_PWM_dutycycle(pin, 0)
        self.duty_cycle = 0

    def set_frequency(self, freq):
        if not isinstance(freq, (int, float)) or freq <= 0:
            raise MotorError("Frequency must be a positive number.")

        ret = self.pi.set_PWM_frequency(self.pin, freq)
        if ret < 0:
            raise MotorError(f"Failed to set PWM frequency: {ret}")

    def set_duty_cycle(self, duty):
        if not isinstance(duty, int) or not (0 <= duty <= 255):
            raise MotorError("Duty cycle must be an integer in the range 0-255.")

        ret = self.pi.set_PWM_dutycycle(self.pin, duty)
        if ret < 0:
            raise MotorError(f"Failed to set PWM duty cycle: {ret}")

        self.duty_cycle = duty

    def stop(self):
        try:
            self.set_duty_cycle(0)
        except MotorError as e:
            print(f"Error stopping motor: {e}")

    def close(self):
        self.stop()
        self.pi.stop()

    def __del__(self):
        self.close()

# Example usage:
if __name__ == "__main__":
    try:
        pi = pigpio.pi()
        motor = Motor(pi, 18)
        motor.set_frequency(1000)
        motor.set_duty_cycle(128)
        time.sleep(2)
        motor.stop()
    except MotorError as e:
        print(f"Motor error: {e}")
    finally:
        if 'motor' in locals():
            motor.close()
        if 'pi' in locals() and pi.connected:
            pi.stop()

