import RPi.GPIO as GPIO
import time
import logging
from contextlib import contextmanager

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ServoController:
    def __init__(self, pin, frequency=50):
        self.pin = pin
        self.frequency = frequency
        self.pwm = None
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.OUT)
            self.pwm = GPIO.PWM(self.pin, self.frequency)
            self.pwm.start(0)
        except Exception as e:
            logging.error(f"Failed to initialize servo on pin {self.pin}: {e}")
            self.cleanup()
            raise

    def _angle_to_duty_cycle(self, angle):
        if not 0 <= angle <= 180:
            raise ValueError("Angle must be between 0 and 180 degrees")
        return 2.5 + (angle / 180) * 10

    def move_to(self, angle):
        duty_cycle = self._angle_to_duty_cycle(angle)
        self.pwm.ChangeDutyCycle(duty_cycle)
        logging.info(f"Moved servo to {angle} degrees with duty cycle {duty_cycle:.2f}%")
        time.sleep(0.5)

    def stop(self):
        if self.pwm:
            self.pwm.ChangeDutyCycle(0)
            self.pwm.stop()
        logging.info("Servo stopped")

    def cleanup(self):
        self.stop()
        GPIO.cleanup(self.pin)
        logging.info("GPIO cleaned up")

@contextmanager
def servo_context(pin):
    servo = ServoController(pin)
    try:
        yield servo
    finally:
        servo.cleanup()

def main_demo(angles):
    with servo_context(18) as servo:
        for angle in angles:
            try:
                servo.move_to(angle)
            except Exception as e:
                logging.error(f"Error moving servo to {angle} degrees: {e}")

if __name__ == "__main__":
    angles = [0, 45, 90, 135, 180, 135, 90, 45, 0]
    try:
        main_demo(angles)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")

