        laser = Laser()
        try:
            for b in nums:
                if 1 <= b <= 10:
                    self.horizontal_servo.value = self.hp[b - 1]
                    self.vertical_servo.value = self.vp[b - 1]
                    time.sleep(self.sd / 2)
                    laser.on()
                    time.sleep(self.ld)
                    laser.off()
                    time.sleep(self.sd / 2)
                    self.horizontal_servo.value = self.hp[10]
