import time
import signal
import sys
from adafruit_servokit import ServoKit

# Constants
BASE = 0
DROP = 1
SEEK = 2
GRAB = 4
METAL = 135
PLASTIC = 180
PAPER = 90
DEFAULT_ANGLE = 90
STEP_SIZE = 5
DELAY = 0.04
DROP_STEP_SIZE = 2
DROP_DELAY = 0.01

# Initialize ServoKit with error handling
try:
    kit = ServoKit(channels=16, address=0x40, i2c_bus=1)
except Exception as e:
    print(f"Error initializing ServoKit: {e}")
    sys.exit(1)

def move_servo(channel, target_angle, step_size=STEP_SIZE, delay=DELAY):
    if not (0 <= channel <= 15):
        raise ValueError("Channel must be between 0 and 15")
    if not (0 <= target_angle <= 180):
        raise ValueError("Angle must be between 0 and 180")

    current_angle = kit.servo[channel].angle
    if current_angle is None:
        current_angle = DEFAULT_ANGLE

    step = step_size if target_angle > current_angle else -step_size
    while abs(target_angle - current_angle) >= step_size:
        current_angle += step
        kit.servo[channel].angle = current_angle
        time.sleep(delay)
    kit.servo[channel].angle = target_angle

def seek(angle):
    move_servo(SEEK, angle)

def deseek(angle):
    move_servo(SEEK, angle)

def drop(angle):
    move_servo(DROP, angle)

def pick(angle):
    move_servo(BASE, angle)

def grab(angle):
    move_servo(GRAB, angle)

def release(angle):
    move_servo(GRAB, angle)

def collect_object_steps(seek_angle):
    seek(seek_angle)
    grab(90)
    drop(160)
    drop(100)
    grab(90)

def drop_object_steps(drop_angle):
    move_servo(DROP, drop_angle, step_size=DROP_STEP_SIZE, delay=DROP_DELAY)
    release(120)
    move_servo(DROP, 100)

def get_pos_x(x_center):
    return max(0, min(180, (x_center / 320) * 180))

def get_pos_y(y_center):
    return max(0, min(180, (y_center / 320) * 180))

def collect_object(x_center, y_center, drop_angle):
    base_angle = get_pos_x(x_center)
    pick(base_angle)
    collect_object_steps(get_pos_y(y_center))
    drop_object_steps(drop_angle)
    for channel in [BASE, DROP, SEEK, GRAB]:
        move_servo(channel, DEFAULT_ANGLE)

def cleanup():
    for channel in range(16):
        kit.servo[channel].angle = DEFAULT_ANGLE
    print("All servos reset to default position.")

def signal_handler(sig, frame):
    print("Exiting gracefully...")
    cleanup()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)

if __name__ == "__main__":
    try:
        # Example usage
        collect_object(160, 160, METAL)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        cleanup()

