import logging
from gpiozero import OutputDevice, Device
from signal import pause, signal, SIGINT

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# GPIO pin numbers
PUMP_PIN = 20
LIGHT_PIN = 21

# Initialize actuators
try:
    pump = OutputDevice(PUMP_PIN)
    light = OutputDevice(LIGHT_PIN)
except Exception as e:
    logging.error(f"Failed to initialize GPIO devices: {e}")
    exit(1)

def parse_intent(phrase):
    """Parse a plain English phrase into a hydroponics control intent."""
    phrase = phrase.lower()
    if "pump on" in phrase:
        return "pump_on"
    elif "pump off" in phrase:
        return "pump_off"
    elif "light" in phrase:
        return "light_toggle"
    else:
        return None

def handle_intent(intent):
    """Handle the parsed intent by controlling the actuators."""
    if intent == "pump_on":
        pump.on()
        logging.info("Pump turned on")
    elif intent == "pump_off":
        pump.off()
        logging.info("Pump turned off")
    elif intent == "light_toggle":
        light.toggle()
        logging.info("Light toggled")
    else:
        logging.warning("Unknown intent: No action taken")

def cleanup():
    """Ensure all actuators are off and resources are released."""
    pump.close()
    light.close()
    logging.info("All actuators turned off and resources released")

def main():
    # List of test phrases
    test_phrases = [
        "turn the pump on",
        "switch the light",
        "turn pump off",
        "unknown command"
    ]

    for phrase in test_phrases:
        logging.info(f"Parsing phrase: '{phrase}'")
        intent = parse_intent(phrase)
        if intent:
            handle_intent(intent)
        else:
            logging.warning(f"Unknown command: '{phrase}'")

    # Wait for a KeyboardInterrupt to exit
    signal(SIGINT, lambda signum, frame: cleanup())
    pause()

if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        logging.error(f"An error occurred: {e}")
        cleanup()

