import smbus2
import time
import signal
import sys

# Constants
I2C_BUS = 1
CCS811_I2C_ADDRESS = 0x5A
APP_START_REGISTER = 0xF4
ALG_RESULT_DATA_REGISTER = 0x02

# Global variables
bus = None

def signal_handler(sig, frame):
    print("Exiting gracefully...")
    if bus:
        bus.close()
    sys.exit(0)

def initialize_sensor():
    try:
        bus.write_byte_data(CCS811_I2C_ADDRESS, APP_START_REGISTER, 0x20)
        time.sleep(1)  # Wait for the sensor to initialize
    except (OSError, IOError) as e:
        print(f"Failed to initialize sensor: {e}")
        return False
    return True

def read_co2_concentration():
    try:
        data = bus.read_i2c_block_data(CCS811_I2C_ADDRESS, ALG_RESULT_DATA_REGISTER, 2)
        co2_concentration = (data[0] << 8) | data[1]
        return co2_concentration
    except (OSError, IOError) as e:
        print(f"Failed to read CO2 concentration: {e}")
        return None

def main():
    global bus
    signal.signal(signal.SIGINT, signal_handler)

    try:
        bus = smbus2.SMBus(I2C_BUS)
        if not initialize_sensor():
            print("Sensor initialization failed.")
            return

        for _ in range(5):
            co2_concentration = read_co2_concentration()
            if co2_concentration is not None:
                print(f"CO2 Concentration: {co2_concentration} ppm")
            time.sleep(2)

    except OSError as e:
        print(f"I2C bus error: {e}")
    except IOError as e:
        print(f"I/O error: {e}")
    finally:
        if bus:
            bus.close()

if __name__ == "__main__":
    main()

