class DS1338:
    def __init__(self, bus_number=1, address=0x68):
        self.bus = smbus2.SMBus(bus_number)
        self.address = address
        self._verify_device()

    def _verify_device(self):
        try:
            self.bus.read_byte(self.address)
        except (smbus2.SMBusError, OSError) as e:
            raise IOError("DS1338 device not found on I2C bus") from e

    def _bcd_to_int(self, bcd):
        return (bcd & 0x0F) + ((bcd >> 4) * 10)

    def _int_to_bcd(self, value):
        return ((value // 10) << 4) + (value % 10)

    def read_seconds(self):
        try:
            return self._bcd_to_int(self.bus.read_byte_data(self.address, 0x00))
        except (smbus2.SMBusError, OSError) as e:
            raise IOError("Failed to read seconds from DS1338") from e

    def write_seconds(self, seconds):
        if not (0 <= seconds <= 59):
            raise ValueError("Seconds must be between 0 and 59")
        try:
            self.bus.write_byte_data(self.address, 0x00, self._int_to_bcd(seconds))
        except (smbus2.SMBusError, OSError) as e:
            raise IOError("Failed to write seconds to DS1338") from e

    def read_minutes(self):
        try:
            return self._bcd_to_int(self.bus.read_byte_data(self.address, 0x01))
        except (smbus2.SMBusError, OSError) as e:
            raise IOError("Failed to read minutes from DS1338") from e

    def write_minutes(self, minutes):
        if not (0 <= minutes <= 59):
            raise ValueError("Minutes must be between 0 and 59")
        try:
            self.bus.write_byte_data(self.address, 0x01, self._int_to_bcd(minutes))
        except (smbus2.SMBusError, OSError) as e:
            raise IOError("Failed to write minutes to DS1338") from e

    def read_hours(self):
        try:
