            return self._bcd_to_int(hours_bcd & 0x3F)
        except (smbus2.SMBusError, OSError) as e:
            raise IOError("Failed to read hours from DS1338") from e

    def write_hours(self, hours):
        if not (0 <= hours <= 23):
            raise ValueError("Hours must be between 0 and 23")
        try:
            self.bus.write_byte_data(self.address, 0x02, self._int_to_bcd(hours) & 0x3F)
        except (smbus2.SMBusError, OSError) as e:
            raise IOError("Failed to write hours to DS1338") from e

    def read_date(self):
