        except (smbus2.SMBusError, OSError) as e:
            raise IOError("Failed to read date from DS1338") from e

    def write_date(self, date):
        if not (1 <= date <= 31):
            raise ValueError("Date must be between 1 and 31")
        try:
            self.bus.write_byte_data(self.address, 0x04, self._int_to_bcd(date))
        except (smbus2.SMBusError, OSError) as e:
            raise IOError("Failed to write date to DS1338") from e

    def read_month(self):
        try:
