        if not (1 <= month <= 12):
            raise ValueError("Month must be between 1 and 12")
        try:
            self.bus.write_byte_data(self.address, 0x05, self._int_to_bcd(month))
        except (smbus2.SMBusError, OSError) as e:
            raise IOError("Failed to write month to DS1338") from e

    def read_year(self):
        try:
