import smbus2
import datetime
import sys
from contextlib import contextmanager

class DS1338:
    I2C_ADDRESS = 0x68
    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06

    def __init__(self, bus_number=1):
        try:
            self.bus = smbus2.SMBus(bus_number)
        except IOError as e:
            raise IOError(f"Failed to open SMBus {bus_number}: {e}")

    def close(self):
        self.bus.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def _bcd_to_dec(self, bcd):
        return (bcd & 0x0F) + ((bcd >> 4) * 10)

    def _dec_to_bcd(self, dec):
        return ((dec // 10) << 4) + (dec % 10)

    def _read_register(self, reg):
        try:
            return self.bus.read_byte_data(self.I2C_ADDRESS, reg)
        except IOError as e:
            raise IOError(f"Failed to read from register 0x{reg:02X}: {e}")

    def _write_register(self, reg, value):
        try:
            self.bus.write_byte_data(self.I2C_ADDRESS, reg, value)
        except IOError as e:
            raise IOError(f"Failed to write to register 0x{reg:02X}: {e}")

    def read_all(self):
        seconds = self._read_register(self.REG_SECONDS) & 0x7F  # Mask CH bit
        minutes = self._read_register(self.REG_MINUTES)
        hours = self._read_register(self.REG_HOURS) & 0x1F  # Mask 12/24-hour bit
        day = self._read_register(self.REG_DAY)
        date = self._read_register(self.REG_DATE)
        month = self._read_register(self.REG_MONTH)
        year = self._read_register(self.REG_YEAR) + 2000  # Assume 2000-2099

        return (year, month, date, day, hours, minutes, seconds)

    def read_datetime(self):
        year, month, date, day, hours, minutes, seconds = self.read_all()
        return datetime.datetime(year, month, date, hours, minutes, seconds, tzinfo=datetime.timezone.utc)

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        if not (2000 <= year <= 2099):
            raise ValueError("Year must be between 2000 and 2099")
