import smbus2
import datetime
import sys
from contextlib import contextmanager

class DS1338:
    I2C_ADDRESS = 0x68
    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06

    def __init__(self, bus_number=1):
        try:
            self.bus = smbus2.SMBus(bus_number)
        except IOError as e:
            raise IOError(f"Failed to open SMBus {bus_number}: {e}")

    def close(self):
        self.bus.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def _bcd_to_dec(self, bcd):
        return (bcd & 0x0F) + ((bcd >> 4) * 10)

    def _dec_to_bcd(self, dec):
        return ((dec // 10) << 4) + (dec % 10)

    def _read_register(self, reg):
        try:
            return self.bus.read_byte_data(self.I2C_ADDRESS, reg)
        except IOError as e:
            raise IOError(f"Failed to read from register 0x{reg:02X}: {e}")

    def _write_register(self, reg, value):
        try:
            self.bus.write_byte_data(self.I2C_ADDRESS, reg, value)
        except IOError as e:
            raise IOError(f"Failed to write to register 0x{reg:02X}: {e}")

    def read_all(self):
        seconds = self._read_register(self.REG_SECONDS) & 0x7F  # Mask CH bit
        minutes = self._read_register(self.REG_MINUTES)
        hours = self._read_register(self.REG_HOURS) & 0x1F  # Mask 12/24-hour bit
        day = self._read_register(self.REG_DAY)
        date = self._read_register(self.REG_DATE)
        month = self._read_register(self.REG_MONTH)
        year = self._read_register(self.REG_YEAR) + 2000  # Assume 2000-2099

        return (year, month, date, day, hours, minutes, seconds)

    def read_datetime(self):
        year, month, date, day, hours, minutes, seconds = self.read_all()
        return datetime.datetime(year, month, date, hours, minutes, seconds, tzinfo=datetime.timezone.utc)

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        if not (2000 <= year <= 2099):
            raise ValueError("Year must be between 2000 and 2099")
        if not (1 <= month <= 12):
            raise ValueError("Month must be between 1 and 12")
        if not (1 <= date <= 31):
            raise ValueError("Date must be between 1 and 31")
        if not (1 <= day <= 7):
            raise ValueError("Day must be between 1 and 7")
        if not (0 <= hours < 24):
            raise ValueError("Hours must be between 0 and 23")
        if not (0 <= minutes < 60):
            raise ValueError("Minutes must be between 0 and 59")
        if not (0 <= seconds < 60):
            raise ValueError("Seconds must be between 0 and 59")

        seconds_bcd = self._dec_to_bcd(seconds) & 0x7F  # Clear CH bit
        minutes_bcd = self._dec_to_bcd(minutes)
        hours_bcd = self._dec_to_bcd(hours) & 0x1F  # Clear 12/24-hour bit
        day_bcd = self._dec_to_bcd(day)
        date_bcd = self._dec_to_bcd(date)
        month_bcd = self._dec_to_bcd(month)
        year_bcd = self._dec_to_bcd(year - 2000)

        self._write_register(self.REG_SECONDS, seconds_bcd)
        self._write_register(self.REG_MINUTES, minutes_bcd)
        self._write_register(self.REG_HOURS, hours_bcd)
        self._write_register(self.REG_DAY, day_bcd)
        self._write_register(self.REG_DATE, date_bcd)
        self._write_register(self.REG_MONTH, month_bcd)
        self._write_register(self.REG_YEAR, year_bcd)

    def write_datetime(self, dt):
        self.write_all(dt.year, dt.month, dt.day, dt.isoweekday(), dt.hour, dt.minute, dt.second)

    def write_now(self):
        self.write_datetime(datetime.datetime.now(datetime.timezone.utc))

if __name__ == "__main__":
