                    co2_ppm = int(co2_data)
                    print(f"{timestamp} - CO2: {co2_ppm} ppm")
                    log_co2_concentration(timestamp, co2_ppm)
                except ValueError:
                    print(f"{timestamp} - Error: Non-numeric CO2 data received: {co2_data}")
            else:
                print(f"{timestamp} - Error: No CO2 data received")

            time.sleep(SAMPLING_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        close_serial_port()
        close_log_file()

if __name__ == "__main__":
    main()

