from datetime import datetime

def parse_gpgga(sentence):
    parts = sentence.split(',')
    if parts[0] != '$GPGGA':
        return None
    if parts[6] != '1':  # Fix quality indicator: 0 = invalid, 1 = GPS fix
        return None
    try:
        latitude = float(parts[2])
        lat_direction = parts[3]
        longitude = float(parts[4])
        lon_direction = parts[5]
        altitude = float(parts[9])
    except ValueError:
        return None

    # Convert latitude and longitude to decimal degrees
    lat_degrees = int(latitude / 100)
    lat_minutes = latitude % 100
    lat_decimal = lat_degrees + (lat_minutes / 60)
    if lat_direction == 'S':
        lat_decimal = -lat_decimal

    lon_degrees = int(longitude / 100)
    lon_minutes = longitude % 100
    lon_decimal = lon_degrees + (lon_minutes / 60)
    if lon_direction == 'W':
        lon_decimal = -lon_decimal

    return lat_decimal, lon_decimal, altitude

def log_coordinates(lat, lon, alt):
    timestamp = datetime.now().isoformat()
    log_entry = f"{timestamp} - Latitude: {lat:.6f}, Longitude: {lon:.6f}, Altitude: {alt:.2f}m\n"
    try:
        with open('gps_coordinates_log.txt', 'a') as log_file:
