import serial
import logging
import signal
import sys
from dataclasses import dataclass
from typing import Optional

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

@dataclass
class GPSReading:
    latitude: float
    longitude: float
    altitude: float
    satellite_count: int

class GPSReader:
    def __init__(self, port: str = '/dev/serial0', baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial: Optional[serial.Serial] = None

    def connect(self) -> bool:
        try:
            self.serial = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            logging.info(f"Connected to GPS on {self.port} at {self.baudrate} baud")
            return True
        except serial.SerialException as e:
            logging.error(f"Failed to connect to GPS on {self.port}: {e}")
            return False

    def disconnect(self) -> None:
        if self.serial and self.serial.is_open:
            self.serial.close()
            logging.info(f"Disconnected from GPS on {self.port}")

    def read_line(self) -> Optional[str]:
        try:
            line = self.serial.readline().decode('utf-8').strip()
            return line
        except serial.SerialException as e:
            logging.warning(f"Serial read error: {e}")
            return None

    def parse_gpgga(self, line: str) -> Optional[GPSReading]:
        parts = line.split(',')
        if len(parts) != 15 or parts[0] != '$GPGGA':
            logging.warning(f"Invalid GPGGA sentence: {line}")
            return None

        try:
            latitude = float(parts[2])
            latitude_direction = parts[3]
            longitude = float(parts[4])
            longitude_direction = parts[5]
            altitude = float(parts[9])
            satellite_count = int(parts[7])

            latitude = latitude / 100.0
            if latitude_direction == 'S':
                latitude = -latitude

            longitude = longitude / 100.0
            if longitude_direction == 'W':
                longitude = -longitude

            return GPSReading(latitude, longitude, altitude, satellite_count)
        except ValueError as e:
            logging.warning(f"Error parsing GPGGA sentence: {e}")
            return None

    def checksum_valid(self, line: str) -> bool:
        parts = line.split('*')
        if len(parts) != 2:
            return False

        data, expected_checksum = parts
        calculated_checksum = 0
        for char in data:
            calculated_checksum ^= ord(char)

        return calculated_checksum == int(expected_checksum, 16)

def signal_handler(sig, frame):
    logging.info("Received signal to exit")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    gps_reader = GPSReader()
    if not gps_reader.connect():
        sys.exit(1)

    try:
        while True:
            line = gps_reader.read_line()
            if line is None:
