import serial
import time
import signal
import sys

class ESP8266:
    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=5, buffersize=4096):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.buffersize = buffersize
        self.serial = None

        # Register signal handler for graceful exit
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        try:
            self.serial = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                timeout=self.timeout,
                write_timeout=self.timeout,
                rtscts=True,
                dsrdtr=True,
                xonxoff=True,
                exclusive=True
            )
            self.serial.set_buffer_size(rx_size=self.buffersize, tx_size=self.buffersize)
        except serial.SerialException as e:
            print(f"Error opening serial port {self.port}: {e}")
            sys.exit(1)

    def _signal_handler(self, signum, frame):
        print(f"Received signal {signum}, exiting...")
        self.close()
        sys.exit(0)

    def _send_command(self, command, delay=1, max_retries=3):
        for attempt in range(max_retries):
            try:
                self.serial.write(command.encode('utf-8'))
                time.sleep(delay)
                response = self._read_response()
                if response:
                    return response
            except serial.SerialException as e:
                print(f"Serial error: {e}")
            except Exception as e:
                print(f"Unexpected error: {e}")
            print(f"Attempt {attempt + 1} failed, retrying...")
        return None

    def _read_response(self):
        start_time = time.time()
        response = bytearray()
        while time.time() - start_time < self.timeout:
            if self.serial.in_waiting > 0:
                response.extend(self.serial.read(self.serial.in_waiting))
                if b'OK' in response or b'ERROR' in response or b'FAIL' in response:
                    return response.decode('utf-8').strip()
        return None

    def test_connection(self):
        response = self._send_command('AT\r\n')
        return response == 'OK'

    def restart(self):
        response = self._send_command('AT+RST\r\n', delay=2)
        return response == 'OK'

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP_CUR="{ssid}","{password}"\r\n'
        response = self._send_command(command, delay=5)
        return 'WIFI GOT IP' in response

    def close(self):
        if self.serial:
            self.serial.close()
            self.serial = None

# Example usage
if __name__ == "__main__":
    esp = ESP8266()
    try:
        if esp.test_connection():
            print("Connection to ESP8266 successful.")
            if esp.restart():
                print("ESP8266 restarted successfully.")
                if esp.connect_wifi('your_ssid', 'your_password'):
                    print("Connected to Wi-Fi successfully.")
                else:
                    print("Failed to connect to Wi-Fi.")
            else:
                print("Failed to restart ESP8266.")
        else:
            print("Failed to connect to ESP8266.")
    finally:
        esp.close()

