from contextlib import contextmanager

class GPSModule:
    def __init__(self, port='/dev/ttyAMA0', baud=9600, timeout=1):
        self.port = port
        self.baud = baud
        self.timeout = timeout
        self.serial = None
        self._open_serial()

    def _open_serial(self):
        try:
            self.serial = serial.Serial(self.port, self.baud, timeout=self.timeout)
        except serial.SerialException as e:
            raise RuntimeError(f"Failed to open serial port {self.port}: {e}")

    def attach(self):
        if not self.serial:
            raise RuntimeError("Serial port is not open")
        try:
            self.serial.write(b'AT+CGNSPWR=1\r\n')
            time.sleep(1)
            response = self.serial.readline().decode('utf-8').strip()
            if response != 'OK':
                raise RuntimeError(f"Failed to power on GNSS: {response}")
        except serial.SerialException as e:
            raise RuntimeError(f"Serial I/O error: {e}")

    def detach(self):
        if not self.serial:
            raise RuntimeError("Serial port is not open")
        try:
            self.serial.write(b'AT+CGNSPWR=0\r\n')
            response = self.serial.readline().decode('utf-8').strip()
            if response != 'OK':
                raise RuntimeError(f"Failed to power off GNSS: {response}")
        except serial.SerialException as e:
            raise RuntimeError(f"Serial I/O error: {e}")

    def get_data(self):
        if not self.serial:
            raise RuntimeError("Serial port is not open")
        try:
            data = self.serial.readline().decode('utf-8').strip()
            if data.startswith('$GPRMC'):
                parts = data.split(',')
                if len(parts) > 2 and parts[2] == 'A':
                    return parts
        except serial.SerialException as e:
            raise RuntimeError(f"Serial I/O error: {e}")
        return None

    def close(self):
        if self.serial:
            self.serial.close()
            self.serial = None

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def _signal_handler(self, signum, frame):
        self.close()
        exit(0)

    def setup_signal_handlers(self):
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

# Example usage:
if __name__ == "__main__":
    gps = GPSModule()
    gps.setup_signal_handlers()
    try:
        gps.attach()
        while True:
            data = gps.get_data()
            if data:
                print("GPS Data:", data)
            time.sleep(1)
    finally:
        gps.detach()
