import serial
import threading
import flask
import signal
import sys
import json

app = flask.Flask(__name__)

class SerialCommunicator:
    def __init__(self):
        self._lock = threading.Lock()
        self._serial = None

    def open(self, port, baudrate):
        with self._lock:
            if self._serial is not None:
                raise RuntimeError("Serial port already open")
            try:
                self._serial = serial.Serial(port, baudrate, timeout=1)
            except serial.SerialException as e:
                self._serial = None
                raise e

    def send(self, cmd):
        with self._lock:
            if self._serial is None:
                raise RuntimeError("Serial port not open")
            self._serial.write(cmd.encode('ascii'))
            if self._serial.write(cmd.encode('ascii')) != len(cmd):
                raise RuntimeError("Failed to write all bytes")
            self._serial.flush()

    def receive_line(self):
        with self._lock:
            if self._serial is None:
                raise RuntimeError("Serial port not open")
            try:
                return self._serial.readline().decode('ascii').strip()
            except serial.SerialException:
                return None

    def close(self):
        with self._lock:
            if self._serial is not None:
                self._serial.close()
                self._serial = None

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

class DataManager:
    def __init__(self):
        self._lock = threading.Lock()
        self._data = [
            {"id": 1, "name": "Item 1", "done": False},
            {"id": 2, "name": "Item 2", "done": True}
        ]

    def get_all(self):
        with self._lock:
            return self._data.copy()

    def get_by_id(self, item_id):
        with self._lock:
            for item in self._data:
                if item["id"] == item_id:
                    return item
            return None

    def create(self, name, done):
        with self._lock:
            if not isinstance(name, str) or not name:
                raise ValueError("Name must be a non-empty string")
            if not isinstance(done, bool):
                raise ValueError("Done must be a boolean")
            new_id = max(item["id"] for item in self._data) + 1 if self._data else 1
            new_item = {"id": new_id, "name": name, "done": done}
            self._data.append(new_item)
            return new_item

data_manager = DataManager()
serial_communicator = SerialCommunicator()

@app.route('/version', methods=['GET'])
def version():
    try:
        with serial_communicator:
            serial_communicator.open('/dev/ttyUSB0', 9600)
            serial_communicator.send('*IDN?\n')
            response = serial_communicator.receive_line()
            if response is None:
                return "No response from device", 504
            return response, 200
    except serial.SerialException:
        return "Failed to open serial port", 500
    except Exception as e:
        return str(e), 502

@app.route('/data', methods=['GET'])
def get_data():
    return json.dumps(data_manager.get_all()), 200

@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_by_id(item_id):
    item = data_manager.get_by_id(item_id)
    if item is None:
        return "Item not found", 404
    return json.dumps(item), 200

@app.route('/data', methods=['POST'])
def create_data():
    try:
        data = flask.request.get_json()
        new_item = data_manager.create(data['name'], data['done'])
        return json.dumps(new_item), 201
    except (KeyError, ValueError) as e:
        return str(e), 400

def signal_handler(sig, frame):
    serial_communicator.close()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False)

