import serial
import time

def read_pulse_oximeter():
    try:
        # Open the serial port
        ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
        print("Serial port opened successfully.")

        try:
            while True:
                try:
                    # Read a line from the serial port
                    line = ser.readline().decode('ascii', errors='replace').strip()

                    if line:
                        # Split the line by comma
                        fields = line.split(',')

                        # Check if the line has exactly two fields
                        if len(fields) != 2:
                            print(f"Warning: Invalid data format - {line}")
                        else:
                            heart_rate, spo2 = fields
                            print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")

                except ValueError as e:
                    print(f"ValueError: {e} - Offending data: {line}")

                # Delay for 1 second between readings
                time.sleep(1)

        except KeyboardInterrupt:
            print("KeyboardInterrupt received. Exiting gracefully.")

        finally:
            # Ensure the serial port is closed
            ser.close()
            print("Serial port closed.")

    except serial.SerialException as e:
        print(f"Serial port error: {e}")

if __name__ == "__main__":
    read_pulse_oximeter()

