from flask import Flask, jsonify, request, abort
import serial
import json

app = Flask(__name__)

# In-memory data store
data_store = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": False}
]

# Auto-incrementing ID counter
next_id = 3

@app.route('/version', methods=['GET'])
def version():
    ser = None
    try:
        ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
        ser.write(b'*IDN?\n')
        response = ser.read(1024).decode('utf-8').replace('\n', '<br>')
        return response, 200, {'Content-Type': 'text/html'}
    except serial.SerialException as e:
        return f"Serial port error: {e}", 503
    finally:
        if ser:
            ser.close()

@app.route('/getdata', methods=['GET'])
def getdata():
    return jsonify(data_store)

@app.route('/getset/<int:item_id>', methods=['GET'])
def getset(item_id):
    item = next((item for item in data_store if item['id'] == item_id), None)
    if item is None:
        abort(404)
    return jsonify(item)

@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def getpost(item_id, name):
    global next_id
    data_store.append({"id": item_id, "name": name, "done": False})
    next_id = max(next_id, item_id + 1)
    return jsonify(data_store)

@app.route('/postjson', methods=['POST'])
def postjson():
    global next_id
    if request.is_json:
        data = request.get_json()
    else:
        data = request.form.to_dict()

    try:
        name = data.get('name', '')
        done = data.get('done', 'False').lower() in ['true', '1', 't', 'y', 'yes']
        new_item = {"id": next_id, "name": name, "done": done}
        data_store.append(new_item)
        next_id += 1
        return jsonify(data_store)
    except Exception as e:
        return f"Malformed input: {e}", 400

@app.route('/postjson', methods=['GET'])
def getpostjson():
    return jsonify(data_store)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

