    except serial.SerialException as e:
        raise RuntimeError(f"Failed to send command: {e}")

def main():
    try:
        # Establish a serial connection to the Bluetooth device
        ser = serial.Serial('/dev/rfcomm4', baudrate=38400, timeout=1)
